namespace Armada.Test.Unit.Suites.Services
{
    using System;
    using System.Collections.Generic;
    using System.Diagnostics;
    using System.IO;
    using System.Threading;
    using System.Threading.Tasks;
    using Armada.Core.Models;
    using Armada.Core.Services;
    using Armada.Test.Common;
    using Armada.Test.Unit.TestHelpers;

    /// <summary>
    /// Real-git tests for preparing a landing candidate with declared generated artifacts: the candidate is built in
    /// a detached worktree, generated bytes are regenerated instead of text-merged, and every refusal leaves the
    /// target branch where it was.
    /// </summary>
    public class GeneratedArtifactLandingTests : TestSuite
    {
        /// <summary>Suite name.</summary>
        public override string Name => "Generated Artifact Landing";

        private const string Manifest = "manifest.json";
        private const string Regenerate = "sh tools/regen.sh";
        private const string RegenerateScript = "#!/bin/sh\nset -e\nLC_ALL=C ls authored | sort > manifest.json\n";

        private sealed class Repo
        {
            public string Root { get; set; } = String.Empty;
            public string Work { get; set; } = String.Empty;
            public string SourceBranch { get; set; } = "armada/captain-b/msn_b";
            public List<string> Commands { get; } = new List<string>();
        }

        /// <summary>Run all generated artifact landing tests.</summary>
        protected override async Task RunTestsAsync()
        {
            await RunTest("A diverged branch whose declared artifact changed on both sides gets a regenerated candidate that needs review", async () =>
            {
                Repo repo = await CreateRepoAsync(mainAdds: "a.txt", branchAdds: "b.txt").ConfigureAwait(false);
                try
                {
                    string mainBefore = await GitAsync(repo.Work, "rev-parse", "main").ConfigureAwait(false);
                    string sourceBefore = await GitAsync(repo.Work, "rev-parse", repo.SourceBranch).ConfigureAwait(false);

                    GeneratedArtifactLandingResult result = await PrepareAsync(repo, Policy()).ConfigureAwait(false);

                    AssertEqual("ReviewRequired", result.Outcome, "the regenerated manifest differs from the reviewed one: " + result.Reason);
                    AssertEqual(mainBefore, result.TargetBaseCommit, "the target base is the target tip");
                    AssertEqual(sourceBefore, result.SourceCommit, "the source is the reviewed branch tip");
                    AssertNotNull(result.CandidateCommit, "a candidate commit is prepared");
                    string manifest = await GitAsync(repo.Work, "show", result.CandidateCommit + ":" + Manifest).ConfigureAwait(false);
                    AssertEqual("a.txt\nb.txt\nbase.txt", manifest, "the candidate manifest is regenerated from both sides' authored files");
                    AssertFalse(manifest.Contains("<<<<<<<", StringComparison.Ordinal), "generated bytes are never text-merged");
                    AssertTrue(await IsAncestorAsync(repo, mainBefore, result.CandidateCommit!).ConfigureAwait(false), "the candidate keeps the target history");
                    AssertTrue(await IsAncestorAsync(repo, sourceBefore, result.CandidateCommit!).ConfigureAwait(false), "the candidate keeps the source history");
                    AssertEqual(1, repo.Commands.Count, "the generator runs once");
                    await AssertRefsUnchangedAsync(repo, mainBefore, sourceBefore).ConfigureAwait(false);
                }
                finally { Cleanup(repo); }
            }).ConfigureAwait(false);

            await RunTest("A branch that only extends the target keeps the ordinary landing and never runs the generator", async () =>
            {
                Repo repo = await CreateRepoAsync(mainAdds: null, branchAdds: "b.txt").ConfigureAwait(false);
                try
                {
                    string mainBefore = await GitAsync(repo.Work, "rev-parse", "main").ConfigureAwait(false);

                    GeneratedArtifactLandingResult result = await PrepareAsync(repo, Policy()).ConfigureAwait(false);

                    AssertEqual("Unchanged", result.Outcome, "a fast-forward needs no regeneration: " + result.Reason);
                    AssertNull(result.CandidateCommit, "no candidate is prepared");
                    AssertEqual(0, repo.Commands.Count, "the generator never runs");
                    AssertEqual(mainBefore, await GitAsync(repo.Work, "rev-parse", "HEAD").ConfigureAwait(false), "no synthetic commit is made");
                }
                finally { Cleanup(repo); }
            }).ConfigureAwait(false);

            await RunTest("A vessel without a declaration keeps the ordinary landing and runs no git or generator", async () =>
            {
                Repo repo = await CreateRepoAsync(mainAdds: "a.txt", branchAdds: "b.txt").ConfigureAwait(false);
                try
                {
                    int gitCalls = 0;
                    GeneratedArtifactLandingResult result = await GeneratedArtifactLanding.PrepareAsync(repo.Work, repo.SourceBranch, null,
                        (args, token) => { gitCalls++; return RunGitAsync(repo.Work, args, token); },
                        (command, token) => { repo.Commands.Add(command); return Task.FromResult(0); }).ConfigureAwait(false);

                    AssertEqual("Unchanged", result.Outcome, "a null declaration keeps existing behaviour");
                    AssertEqual(0, gitCalls, "no git command runs");
                    AssertEqual(0, repo.Commands.Count, "the generator never runs");
                }
                finally { Cleanup(repo); }
            }).ConfigureAwait(false);

            await RunTest("A declared artifact that the target lacks is created by the generator, not refused", async () =>
            {
                foreach (bool mainCommitsManifest in new[] { false, true })
                {
                    string name = mainCommitsManifest ? "both sides add it" : "only the branch adds it";
                    Repo repo = await CreateRepoAsync(mainAdds: "a.txt", branchAdds: "b.txt", manifestOnBase: false,
                        mainCommitsManifest: mainCommitsManifest).ConfigureAwait(false);
                    try
                    {
                        string mainBefore = await GitAsync(repo.Work, "rev-parse", "main").ConfigureAwait(false);
                        string sourceBefore = await GitAsync(repo.Work, "rev-parse", repo.SourceBranch).ConfigureAwait(false);

                        GeneratedArtifactLandingResult result = await PrepareAsync(repo, Policy()).ConfigureAwait(false);

                        AssertEqual("ReviewRequired", result.Outcome, name + ": the artifact is regenerated on the merged tree: " + result.Reason);
                        AssertEqual("a.txt\nb.txt\nbase.txt", await GitAsync(repo.Work, "show", result.CandidateCommit + ":" + Manifest).ConfigureAwait(false),
                            name + ": the generator creates the artifact from both sides");
                        await AssertRefsUnchangedAsync(repo, mainBefore, sourceBefore).ConfigureAwait(false);
                    }
                    finally { Cleanup(repo); }
                }
            }).ConfigureAwait(false);

            await RunTest("A conflict on an authored file fails naming the file and never runs the generator", async () =>
            {
                Repo repo = await CreateRepoAsync(mainAdds: "a.txt", branchAdds: "b.txt", authoredConflict: true).ConfigureAwait(false);
                try
                {
                    string mainBefore = await GitAsync(repo.Work, "rev-parse", "main").ConfigureAwait(false);
                    string sourceBefore = await GitAsync(repo.Work, "rev-parse", repo.SourceBranch).ConfigureAwait(false);

                    GeneratedArtifactLandingResult result = await PrepareAsync(repo, Policy()).ConfigureAwait(false);

                    AssertEqual("Failed", result.Outcome, "an authored conflict is not resolved by regeneration");
                    AssertStartsWith("generated_authored_conflict", result.Reason ?? String.Empty, "the reason classifies the conflict");
                    AssertContains("src/app.txt", result.Reason ?? String.Empty, "the reason names the conflicted file");
                    AssertNull(result.CandidateCommit, "no candidate is prepared");
                    AssertEqual(0, repo.Commands.Count, "the generator never runs");
                    await AssertRefsUnchangedAsync(repo, mainBefore, sourceBefore).ConfigureAwait(false);
                }
                finally { Cleanup(repo); }
            }).ConfigureAwait(false);

            await RunTest("A generator that fails, throws, moves HEAD or writes outside the declaration leaves no candidate", async () =>
            {
                GeneratedArtifactCommandCase[] cases =
                {
                    new GeneratedArtifactCommandCase("non-zero exit", (r, c, t) => ShellAsync(r, "exit 3", t), "generated_command_failed"),
                    new GeneratedArtifactCommandCase("exception", (r, c, t) => throw new TimeoutException("generator timed out"), "generated_command_failed: TimeoutException"),
                    new GeneratedArtifactCommandCase("moves HEAD", (r, c, t) => ShellAsync(r, "sh tools/regen.sh && git add -A && git commit -q -m sneak", t), "generated_command_changed_head"),
                    new GeneratedArtifactCommandCase("undeclared write", (r, c, t) => ShellAsync(r, "sh tools/regen.sh && echo x > outside.txt", t), "generated_undeclared_write: outside.txt"),
                    new GeneratedArtifactCommandCase("ignored undeclared write", (r, c, t) => ShellAsync(r, "sh tools/regen.sh && echo x > cache.tmp", t), "generated_undeclared_write: cache.tmp"),
                    new GeneratedArtifactCommandCase("symlink at declared path", (r, c, t) => ShellAsync(r, "rm -f manifest.json && ln -s /etc/hostname manifest.json", t), "generated_preparation_failed: generated_symlink_escape")
                };

                foreach (GeneratedArtifactCommandCase item in cases)
                {
                    Repo repo = await CreateRepoAsync(mainAdds: "a.txt", branchAdds: "b.txt").ConfigureAwait(false);
                    try
                    {
                        string mainBefore = await GitAsync(repo.Work, "rev-parse", "main").ConfigureAwait(false);
                        string sourceBefore = await GitAsync(repo.Work, "rev-parse", repo.SourceBranch).ConfigureAwait(false);

                        GeneratedArtifactLandingResult result = await GeneratedArtifactLanding.PrepareAsync(repo.Work, repo.SourceBranch, Policy(),
                            (args, token) => RunGitAsync(repo.Work, args, token),
                            (command, token) => item.Run(repo.Work, command, token)).ConfigureAwait(false);

                        AssertEqual("Failed", result.Outcome, item.Name + ": the candidate is refused");
                        AssertStartsWith(item.Reason, result.Reason ?? String.Empty, item.Name + ": the reason names the refusal");
                        AssertNull(result.CandidateCommit, item.Name + ": no candidate is prepared");
                        await AssertRefsUnchangedAsync(repo, mainBefore, sourceBefore).ConfigureAwait(false);
                    }
                    finally { Cleanup(repo); }
                }
            }).ConfigureAwait(false);

            await RunTest("A cancelled generator propagates the cancellation instead of reporting a failure", async () =>
            {
                Repo repo = await CreateRepoAsync(mainAdds: "a.txt", branchAdds: "b.txt").ConfigureAwait(false);
                try
                {
                    bool cancelled = false;
                    try
                    {
                        await GeneratedArtifactLanding.PrepareAsync(repo.Work, repo.SourceBranch, Policy(),
                            (args, token) => RunGitAsync(repo.Work, args, token),
                            (command, token) => throw new OperationCanceledException()).ConfigureAwait(false);
                    }
                    catch (OperationCanceledException)
                    {
                        cancelled = true;
                    }

                    AssertTrue(cancelled, "cancellation is not turned into a Failed result");
                }
                finally { Cleanup(repo); }
            }).ConfigureAwait(false);

            await RunTest("An unusable declaration or worktree is refused before the generator runs", async () =>
            {
                GeneratedArtifactPolicyCase[] cases =
                {
                    new GeneratedArtifactPolicyCase("parent path", Policy("../manifest.json"), false, "generated_preparation_failed: generated_path_invalid"),
                    new GeneratedArtifactPolicyCase("rooted path", Policy("/tmp/manifest.json"), false, "generated_preparation_failed: generated_path_invalid"),
                    new GeneratedArtifactPolicyCase("git directory", Policy(".git/config"), false, "generated_preparation_failed: generated_path_invalid"),
                    new GeneratedArtifactPolicyCase("duplicate path", new GeneratedArtifactPolicy { Paths = new List<string> { Manifest, Manifest }, RegenerateCommand = Regenerate }, false, "generated_preparation_failed: generated_path_invalid"),
                    new GeneratedArtifactPolicyCase("no command", new GeneratedArtifactPolicy { Paths = new List<string> { Manifest }, RegenerateCommand = "" }, false, "generated_preparation_failed: generated_declaration_incomplete"),
                    new GeneratedArtifactPolicyCase("dirty worktree", Policy(), true, "generated_worktree_dirty"),
                    new GeneratedArtifactPolicyCase("ignored dirty worktree", Policy(), true, "generated_worktree_dirty")
                };

                foreach (GeneratedArtifactPolicyCase item in cases)
                {
                    Repo repo = await CreateRepoAsync(mainAdds: "a.txt", branchAdds: "b.txt").ConfigureAwait(false);
                    try
                    {
                        if (item.Dirty) await File.WriteAllTextAsync(Path.Combine(repo.Work, item.Name == "ignored dirty worktree" ? "stray.tmp" : "stray.txt"), "stray\n").ConfigureAwait(false);
                        string mainBefore = await GitAsync(repo.Work, "rev-parse", "main").ConfigureAwait(false);
                        string sourceBefore = await GitAsync(repo.Work, "rev-parse", repo.SourceBranch).ConfigureAwait(false);

                        GeneratedArtifactLandingResult result = await PrepareAsync(repo, item.Policy).ConfigureAwait(false);

                        AssertEqual("Failed", result.Outcome, item.Name + ": refused");
                        AssertStartsWith(item.Reason, result.Reason ?? String.Empty, item.Name + ": the reason names the refusal");
                        AssertEqual(0, repo.Commands.Count, item.Name + ": the generator never runs");
                        await AssertRefsUnchangedAsync(repo, mainBefore, sourceBefore).ConfigureAwait(false);
                    }
                    finally { Cleanup(repo); }
                }
            }).ConfigureAwait(false);
        }

        private static GeneratedArtifactPolicy Policy(string path = Manifest)
        {
            return new GeneratedArtifactPolicy { Paths = new List<string> { path }, RegenerateCommand = Regenerate };
        }

        private static Task<GeneratedArtifactLandingResult> PrepareAsync(Repo repo, GeneratedArtifactPolicy policy)
        {
            return GeneratedArtifactLanding.PrepareAsync(repo.Work, repo.SourceBranch, policy,
                (args, token) => RunGitAsync(repo.Work, args, token),
                (command, token) =>
                {
                    repo.Commands.Add(command);
                    return ShellAsync(repo.Work, command, token);
                });
        }

        /// <summary>
        /// A work repository on <c>main</c> holding an authored directory, a generator and its manifest. The source
        /// branch adds <paramref name="branchAdds"/> and regenerates; main then adds <paramref name="mainAdds"/> and
        /// regenerates, so both sides change the manifest. With no main change the branch is a fast-forward. Without
        /// <paramref name="manifestOnBase"/> the base has no manifest, and main commits one only with
        /// <paramref name="mainCommitsManifest"/>.
        /// </summary>
        private static async Task<Repo> CreateRepoAsync(
            string? mainAdds, string branchAdds, bool manifestOnBase = true, bool mainCommitsManifest = true, bool authoredConflict = false)
        {
            Repo repo = new Repo();
            repo.Root = Path.Combine(Path.GetTempPath(), "armada_generated_landing_" + Guid.NewGuid().ToString("N"));
            repo.Work = Path.Combine(repo.Root, "work");
            Directory.CreateDirectory(Path.Combine(repo.Work, "authored"));
            Directory.CreateDirectory(Path.Combine(repo.Work, "tools"));
            Directory.CreateDirectory(Path.Combine(repo.Work, "src"));
            await GitAsync(repo.Work, "init", "-q", "-b", "main").ConfigureAwait(false);
            await GitAsync(repo.Work, "config", "user.name", "Armada Tests").ConfigureAwait(false);
            await GitAsync(repo.Work, "config", "user.email", "armada-tests@example.com").ConfigureAwait(false);
            await File.WriteAllTextAsync(Path.Combine(repo.Work, "tools", "regen.sh"), RegenerateScript).ConfigureAwait(false);
            await File.WriteAllTextAsync(Path.Combine(repo.Work, ".gitignore"), "*.tmp\n").ConfigureAwait(false);
            await File.WriteAllTextAsync(Path.Combine(repo.Work, "authored", "base.txt"), "base\n").ConfigureAwait(false);
            await File.WriteAllTextAsync(Path.Combine(repo.Work, "src", "app.txt"), "original line\n").ConfigureAwait(false);
            if (manifestOnBase) await ShellAsync(repo.Work, Regenerate, default).ConfigureAwait(false);
            await GitAsync(repo.Work, "add", "-A").ConfigureAwait(false);
            await GitAsync(repo.Work, "commit", "-q", "-m", "Base").ConfigureAwait(false);

            await GitAsync(repo.Work, "checkout", "-q", "-b", repo.SourceBranch).ConfigureAwait(false);
            await File.WriteAllTextAsync(Path.Combine(repo.Work, "authored", branchAdds), "branch\n").ConfigureAwait(false);
            if (authoredConflict) await File.WriteAllTextAsync(Path.Combine(repo.Work, "src", "app.txt"), "branch line\n").ConfigureAwait(false);
            await ShellAsync(repo.Work, Regenerate, default).ConfigureAwait(false);
            await GitAsync(repo.Work, "add", "-A").ConfigureAwait(false);
            await GitAsync(repo.Work, "commit", "-q", "-m", "Branch adds an authored file").ConfigureAwait(false);

            await GitAsync(repo.Work, "checkout", "-q", "main").ConfigureAwait(false);
            if (mainAdds != null)
            {
                await File.WriteAllTextAsync(Path.Combine(repo.Work, "authored", mainAdds), "main\n").ConfigureAwait(false);
                if (authoredConflict) await File.WriteAllTextAsync(Path.Combine(repo.Work, "src", "app.txt"), "main line\n").ConfigureAwait(false);
                if (manifestOnBase || mainCommitsManifest) await ShellAsync(repo.Work, Regenerate, default).ConfigureAwait(false);
                await GitAsync(repo.Work, "add", "-A").ConfigureAwait(false);
                await GitAsync(repo.Work, "commit", "-q", "-m", "Main adds an authored file").ConfigureAwait(false);
            }

            await GitAsync(repo.Work, "checkout", "-q", "--detach", "main").ConfigureAwait(false);
            return repo;
        }

        private async Task AssertRefsUnchangedAsync(Repo repo, string mainBefore, string sourceBefore)
        {
            AssertEqual(mainBefore, await GitAsync(repo.Work, "rev-parse", "main").ConfigureAwait(false), "the target branch is not moved");
            AssertEqual(sourceBefore, await GitAsync(repo.Work, "rev-parse", repo.SourceBranch).ConfigureAwait(false), "the source branch is not moved");
        }

        private static async Task<bool> IsAncestorAsync(Repo repo, string ancestor, string descendant)
        {
            GeneratedArtifactGitOutput result = await RunGitAsync(repo.Work, new[] { "merge-base", "--is-ancestor", ancestor, descendant }, default).ConfigureAwait(false);
            return result.ExitCode == 0;
        }

        private static void Cleanup(Repo repo)
        {
            try { Directory.Delete(repo.Root, true); }
            catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
            { Console.Error.WriteLine("Generated artifact fixture cleanup failed: " + ex.Message); }
        }

        private static async Task<string> GitAsync(string workingDir, params string[] args)
        {
            GeneratedArtifactGitOutput result = await RunGitAsync(workingDir, args, default).ConfigureAwait(false);
            if (result.ExitCode != 0) throw new InvalidOperationException("git " + String.Join(" ", args) + " exited " + result.ExitCode);
            return result.StandardOutput.TrimEnd('\n');
        }

        private static async Task<GeneratedArtifactGitOutput> RunGitAsync(string workingDir, string[] args, CancellationToken token)
        {
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = "git",
                WorkingDirectory = workingDir,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                CreateNoWindow = true
            };
            foreach (string arg in args) startInfo.ArgumentList.Add(arg);

            using (Process proc = new Process { StartInfo = startInfo })
            {
                proc.Start();
                Task<string> stderr = proc.StandardError.ReadToEndAsync(token);
                string stdout = await proc.StandardOutput.ReadToEndAsync(token).ConfigureAwait(false);
                await stderr.ConfigureAwait(false);
                await proc.WaitForExitAsync(token).ConfigureAwait(false);
                return new GeneratedArtifactGitOutput(proc.ExitCode, stdout);
            }
        }

        private static async Task<int> ShellAsync(string workingDir, string command, CancellationToken token)
        {
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = "sh",
                WorkingDirectory = workingDir,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                CreateNoWindow = true
            };
            startInfo.ArgumentList.Add("-c");
            startInfo.ArgumentList.Add(command);

            using (Process proc = new Process { StartInfo = startInfo })
            {
                proc.Start();
                Task<string> stderr = proc.StandardError.ReadToEndAsync(token);
                await proc.StandardOutput.ReadToEndAsync(token).ConfigureAwait(false);
                await stderr.ConfigureAwait(false);
                await proc.WaitForExitAsync(token).ConfigureAwait(false);
                return proc.ExitCode;
            }
        }
    }
}
